import 'card_validator.dart';

/// Data model representing a tokenized card compliant with RBI Card-on-File Tokenization (CoFT) norms.
///
/// Under RBI guidelines, merchants, payment aggregators, and fintechs are prohibited
/// from storing real credit or debit card PANs. Instead, network-issued tokens are retained.
class BharatCardToken {
  static final RegExp _fourDigitsRegex = RegExp(r'^\d{4}$');

  /// The network-issued token string (substituting the real 16-digit PAN).
  final String token;

  /// Token Reference Number (TRN) generated by the card network (RuPay / Visa / Mastercard).
  final String tokenReferenceNumber;

  /// The last 4 digits of the actual card (permitted by RBI for card identification).
  final String lastFour;

  /// The card network / scheme.
  final BharatCardType cardType;

  /// Expiry month of the token (1 - 12).
  final int expiryMonth;

  /// Expiry year of the token (e.g. 2028).
  final int expiryYear;

  /// Optional bank institution that issued the card.
  final String? issuerBank;

  const BharatCardToken({
    required this.token,
    required this.tokenReferenceNumber,
    required this.lastFour,
    required this.cardType,
    required this.expiryMonth,
    required this.expiryYear,
    this.issuerBank,
  });

  /// Validates the token structure according to RBI CoFT standards.
  bool get isValid {
    if (token.trim().isEmpty) return false;
    if (tokenReferenceNumber.trim().isEmpty) return false;
    if (lastFour.length != 4 || !_fourDigitsRegex.hasMatch(lastFour)) {
      return false;
    }
    return BharatCard.validateExpiry(expiryMonth, expiryYear);
  }

  /// Safe display representation (e.g. `RuPay ending in 1234 (Exp 12/28)`).
  String get displayName {
    final typeName = cardType == BharatCardType.rupay
        ? 'RuPay'
        : cardType.name.toUpperCase();
    final bankPrefix = issuerBank != null ? '$issuerBank ' : '';
    final monthStr = expiryMonth.toString().padLeft(2, '0');
    final yearStr = (expiryYear % 100).toString().padLeft(2, '0');
    return '$bankPrefix$typeName •••• $lastFour (Exp $monthStr/$yearStr)';
  }

  @override
  String toString() => displayName;
}
